from datetime import datetime, timezone
from decimal import Decimal
from ledgerly.models import Payment
from ledgerly.payments import capture_partial
from ledgerly.errors import BillingError
T0=datetime(2026,1,1,tzinfo=timezone.utc)
def mk(status="authorized", amt="100.00"):
    return Payment("p","i",Decimal(amt),status=status,created_at=T0)
# zero
for amt in ["0.00","-1.00"]:
    try: capture_partial(mk(),Decimal(amt),T0); print("FAIL zero",amt)
    except BillingError as e: print("ok zero",e.code)
# exceeds
try: capture_partial(mk(),Decimal("100.01"),T0); print("FAIL exceeds")
except BillingError as e: print("ok exceeds",e.code)
# non-authorized
for st in ["captured","voided","refunded"]:
    try: capture_partial(mk(st),Decimal("10.00"),T0); print("FAIL nonauth",st)
    except BillingError as e: print("ok nonauth",st,e.code)
# rounding
p=mk(); capture_partial(p,Decimal("60.005"),T0); print("round",p.amount,p.status,p.captured_at)
# exact authorized
p=mk(); capture_partial(p,Decimal("100.00"),T0); print("exact",p.amount,p.status)
EOF"}

